/* Views based on the club's Google Sheets snapshot. Local edits never change the source. */
const sourceLink = `<a class="link" href="${esc(seed.source.url)}" target="_blank" rel="noopener">Mở Google Sheets ↗</a>`;
const sourceLine = () => !isAdmin()?'':`<div class="source-note"><span>Google Sheets · PTIT × Rikkei · Cơ sở Hà Nội · Cập nhật ${date(seed.source.snapshotDate)}</span>${sourceLink}</div>`;
const amount = value => value == null ? 'Chưa xác định' : money(value);
const paidCount = () => db.members.filter(m=>m.duesStatus==='Đã đóng').length;
const readyCount = () => db.members.filter(m=>m.status==='Sẵn sàng').length;
const sum = (rows, key='amount') => rows.reduce((total,row)=>total+(Number(row[key])||0),0);
const departments = () => [...new Set(db.tasks.map(t=>t.department))];
function metric(icon,title,value,detail){return `<div class="stat"><span class="icon">${icon}</span><div class="muted">${title}</div><div class="number">${value}</div><div class="metric-detail">${detail}</div></div>`}
function stats(){return `<div class="stats">${metric('♧','Thành viên trong danh sách',db.members.length,`${readyCount()} sẵn sàng · ${db.members.filter(m=>m.status==='Chờ xác nhận').length} chờ xác nhận`)}${metric('✓','Đã đóng quỹ tháng đầu',`${paidCount()} / ${db.members.length}`,`${money(db.finance.monthlyFee)} / người theo nguồn`)}${metric('↗','Quỹ thực thu theo Sheets',money(seed.finance.received),'Số liệu tổng hợp tại thời điểm nhập')}${metric('▤','Chi phí dự kiến',money(sum(db.budget)),'Dự trù · chưa phải khoản đã chi')}</div>`}
function discrepancy(){return `<div class="notice"><b>Cần đối chiếu số thành viên:</b> danh sách nguồn có ${seed.summary.memberCount} người; bảng quỹ lấy ${seed.finance.basisMembers} người làm cơ sở tính. Giữ nguyên mức dự kiến ${money(seed.finance.expected)} của bảng quỹ, không tự tính lại theo danh sách.</div>`}
function login(){userId=null;sessionStorage.removeItem('rikkei-source-user');$('#app').innerHTML=`<div class="login"><div class="loginart"><div class="brand" style="margin:0"><div class="crest">R</div><div>RIKKEI FC<small>PTIT × RIKKEI · HÀ NỘI</small></div></div><span class="chip" style="align-self:flex-start;margin-top:50px">MÙA ĐẦU TIÊN · CÙNG NHAU RA SÂN</span><h1>Một đội bóng.<br>Một tinh thần.<br>Một gia đình.</h1><p style="color:#c2d7cb">${seed.summary.memberCount} thành viên · ${seed.summary.taskCount} đầu việc · ${seed.summary.venueCount} sân đang khảo sát<br>Không gian quản lý từ dữ liệu thực tế của CLB.</p></div><div class="loginform"><span class="badge red">KHÔNG GIAN CÂU LẠC BỘ</span><h1 style="margin-top:20px">Chào mừng đồng đội</h1><p class="muted">Chọn không gian quản lý hoặc tên của bạn để truy cập bản trải nghiệm.</p><form id="loginForm"><div class="field"><label for="account">Không gian truy cập</label><select id="account" name="account"><optgroup label="Vai trò dùng thử (không tính là thành viên)">${accessAccounts.map(m=>`<option value="${m.id}">${esc(m.role)}</option>`).join('')}</optgroup><optgroup label="Thành viên từ Google Sheets">${db.members.filter(m=>!m.locked).map(m=>`<option value="${m.id}">${esc(m.name)} · ${esc(m.unit)}</option>`).join('')}</optgroup></select></div><div class="field"><label for="password">Mật khẩu dùng thử</label><input id="password" name="password" type="password" required placeholder="rikkei123" autocomplete="current-password"></div><button class="btn primary">Vào câu lạc bộ →</button><p id="loginError" role="alert" style="color:var(--red)"></p></form><div class="demo"><b>Mật khẩu dùng thử: rikkei123</b><br>Dữ liệu nhập từ Google Sheets ngày ${date(seed.source.snapshotDate)}. Đăng nhập và phân quyền đang mô phỏng; dữ liệu chỉnh sửa lưu ở trình duyệt này.</div><p>${sourceLink}</p></div></div>`;$('#loginForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if(f.get('password')!=='rikkei123'){$('#loginError').textContent='Mật khẩu dùng thử là rikkei123.';return}userId=f.get('account');sessionStorage.setItem('rikkei-source-user',userId);page='dashboard';render();toast('Đã mở không gian câu lạc bộ')}}
function chart(){const paid=paidCount(),total=db.members.length,percent=total?paid/total*100:0;return `<div class="panelhead"><h2>Tiến độ đóng quỹ tháng đầu</h2><span class="badge">${paid} / ${total} người</span></div><div class="dues-progress"><div style="width:${percent}%"></div></div><div class="matchbottom"><div><b>${percent.toFixed(0)}% đã đóng</b><p class="muted">${total-paid} người chưa được đánh dấu đã đóng</p></div><button class="link" data-page="finance">Xem danh sách →</button></div><p class="muted">Nguồn chưa có ngày thu từng người hoặc lịch sử theo tháng. Trạng thái đóng quỹ không tự tạo giao dịch thu.</p>`}
function summaryTasks(){const rows=db.tasks.filter(t=>t.status!=='Hoàn thành').slice(0,4);return taskRows(null,rows)}
views.dashboard=()=>head(me().accessOnly?'Tổng quan câu lạc bộ':`Xin chào, ${esc(me().name.split(' ').slice(-2).join(' '))}!`,'PTIT × Rikkei · Cơ sở Hà Nội',can('events')?button('＋ Tạo buổi đá','eventForm','',true):button('Xem lịch hoạt động','gotoEvents'))+sourceLine()+stats()+`<div class="grid"><div><section class="panel"><div class="panelhead"><h2>Hẹn nhau trên sân cỏ</h2><button class="link" data-page="events">Lịch hoạt động →</button></div>${db.events.length?nextMatch():`<div class="hero"><span class="badge">LỊCH DỰ KIẾN THEO BẢNG NGUỒN</span><div class="teams">THỨ NĂM <span>HẰNG TUẦN</span></div><div class="matchmeta"><span>◷ 19:30 – 21:00</span><span>⌖ ${db.venues.some(v=>v.confirmed)?esc(db.venues.filter(v=>v.confirmed).map(v=>v.name).join(', ')):'Hà Nội · Đang khảo sát sân'}</span></div></div><p class="muted">${db.venues.some(v=>v.confirmed)?'Đã chốt '+esc(db.venues.filter(v=>v.confirmed).map(v=>v.name).join(', '))+'. Chưa có ngày đá cụ thể.':'Chưa có sân chốt hoặc ngày đá cụ thể. Có '+db.venues.length+' sân trong danh sách khảo sát.'}</p>${can('events')||can('logistics')?`<button class="link" data-page="venues">Xem danh sách sân →</button>`:''}`}</section><section class="panel">${chart()}</section><section class="panel"><div class="panelhead"><h2>Thao tác nhanh</h2></div><div class="quick">${[['▦','Xem lịch đá','gotoEvents'],...(can('members')?[['♧','Thành viên','gotoMembers']]:[['◎','Hồ sơ cá nhân','gotoProfile']]),...(can('finance')?[['↗','Ghi khoản thu','income'],['↘','Ghi khoản chi','expense']]:[['◈','Theo dõi quỹ','gotoFinance'],['▤','Đơn xin vắng','gotoRequests']])].map(([i,t,a])=>`<button data-action="${a}"><b>${i}</b>${t}</button>`).join('')}</div></section></div><div><section class="panel"><div class="panelhead"><h2>Công việc đang triển khai</h2><span class="muted">${db.tasks.filter(t=>t.status==='Hoàn thành').length}/${db.tasks.length} hoàn thành</span></div>${summaryTasks()}</section><section class="panel"><div class="panelhead"><h2>Ghi nhận từ dữ liệu nguồn</h2></div>${discrepancy()}<p class="muted">Nguồn chưa có sổ thu chi thực tế, kết quả trận đấu hoặc lịch hoạt động theo ngày. Các mục này sẵn sàng để CLB bổ sung.</p>${sourceLink}</section></div></div>`;
function memberTable(ms){return `<table class="wide-table"><thead><tr><th>THÀNH VIÊN</th><th>LỚP</th><th>VỊ TRÍ / VAI TRÒ</th><th>THAM GIA</th><th>QUỸ THÁNG ĐẦU</th><th></th></tr></thead><tbody>${ms.map(m=>`<tr><td><div class="user"><span class="avatar">${initials(m.name)}</span><div><b>${esc(m.name)}</b><div class="muted">${m.sourceIndex?'STT '+m.sourceIndex:'Mới'}</div></div></div></td><td>${esc(m.unit||'Chưa cập nhật')}</td><td class="table-note">${esc(m.sourcePosition||m.positions?.join(', ')||'Chưa cập nhật')}</td><td>${tag(m.status)}${m.locked?tag('Tài khoản khóa'):''}</td><td>${tag(m.duesStatus)}${m.receipts?.length?`<div><button class="link" data-action="memberReceipts" data-id="${m.id}">${m.receipts.length} ảnh bill</button></div>`:''}</td><td><button class="link" data-action="memberForm" data-id="${m.id}">Chi tiết / Sửa</button></td></tr>`).join('')}</tbody></table>${ms.length?'':'<div class="empty">Không có thành viên phù hợp.</div>'}`}
views.members=()=>head('Thành viên CLB',`${db.members.length} thành viên · ${readyCount()} sẵn sàng · ${paidCount()} đã đóng quỹ`,can('members')?button('＋ Thêm thành viên','memberForm','',true):'')+sourceLine()+`<section class="panel"><div class="filters"><input id="memberSearch" placeholder="Tìm tên, lớp, số thứ tự…"><select id="memberPosition"><option value="">Mọi vị trí</option>${['Thủ Môn','Hậu Vệ','Tiền Vệ','Tiền Đạo','Quản Lý Đội','Hậu Cần','Truyền Thông'].map(v=>`<option>${v}</option>`).join('')}</select><select id="memberStatus"><option value="">Mọi trạng thái tham gia</option>${['Sẵn sàng','Chờ xác nhận','Tạm nghỉ','Đã rời CLB'].map(v=>`<option>${v}</option>`).join('')}</select><select id="memberDues"><option value="">Mọi trạng thái đóng quỹ</option><option>Đã đóng</option><option>Chưa đóng</option></select>${button('↓ Xuất CSV','exportMembers')}</div><div id="memberTable" class="tablewrap">${memberTable(db.members)}</div></section>`;
function filteredMembers(){const value=id=>$('#'+id)?.value||'';return db.members.filter(m=>(m.name+' '+m.unit+' '+(m.sourceIndex||'')).toLowerCase().includes(value('memberSearch').toLowerCase())&&(!value('memberPosition')||m.sourcePosition.toLowerCase().includes(value('memberPosition').toLowerCase()))&&(!value('memberStatus')||m.status===value('memberStatus'))&&(!value('memberDues')||m.duesStatus===value('memberDues')))}
function memberForm(id,personal=false){if(!personal&&!can('members'))return;const m=db.members.find(m=>m.id===id)||{id:uid(),name:'',email:'',phone:'',role:roles[5],department:'',status:'Chờ xác nhận',joined:'',unit:'',sourcePosition:'',positions:[],duesStatus:'Chưa đóng',note:'',note2:'',receipts:[],locked:false};modal(personal?'Hồ sơ cá nhân':id?'Thông tin thành viên':'Thêm thành viên',form(`${m.source?`<p class="muted">Nguồn: ${esc(m.source.sheet)} · hàng ${m.source.row}</p>`:''}<div class="formgrid">${field('Họ tên','name',m.name)}${field('Lớp / Bộ phận','unit',m.unit,'text',false)}${field('Email','email',m.email,'email',false)}${field('Số điện thoại','phone',m.phone,'tel',false)}</div>${field('Vị trí thi đấu / Vai trò trong đội','sourcePosition',m.sourcePosition,'text',false)}${personal?'':`<div class="formgrid">${select('Tình trạng tham gia','status',['Sẵn sàng','Chờ xác nhận','Tạm nghỉ','Đã rời CLB'],m.status)}${field('Ban','department',m.department,'text',false)}${field('Ngày tham gia','joined',m.joined,'date',false)}${isAdmin()?select('Quyền tài khoản','role',roles,m.role):''}</div>${area('Ghi chú','note',m.note)}${area('Ghi chú 2','note2',m.note2)}${isAdmin()?select('Tài khoản','locked',[['false','Mở tài khoản'],['true','Khóa tài khoản']],String(m.locked)):''}<p>Đóng quỹ tháng đầu: ${tag(m.duesStatus)} · Quản lý tại mục Quỹ & thu chi.</p>`}`,id&&!personal&&isAdmin()?`<button type="button" class="btn" data-action="deleteMember" data-id="${id}">Xóa thành viên</button>`:''));handleForm(d=>{if(d.email&&db.members.some(x=>x.id!==m.id&&x.email===d.email))throw Error('Email này đã được sử dụng.');const value={...d,positions:d.sourcePosition.split(',').map(s=>s.trim()).filter(Boolean)};if(!isAdmin()){delete value.role;delete value.locked}else if('locked'in d)value.locked=d.locked==='true';Object.assign(m,value,{localUpdatedAt:new Date().toISOString()});if(!id)db.members.push(m)})}
function duesRows(ms){return `<table><thead><tr><th>THÀNH VIÊN</th><th>LỚP</th><th>TRẠNG THÁI</th><th>MINH CHỨNG</th><th></th></tr></thead><tbody>${ms.map(m=>`<tr><td><b>${esc(m.name)}</b></td><td>${esc(m.unit)}</td><td>${tag(m.duesStatus)}</td><td>${m.receipts?.length?`<button class="link" data-action="memberReceipts" data-id="${m.id}">Xem ${m.receipts.length} ảnh</button>`:'Chưa có ảnh gắn với dòng này'}</td><td>${can('finance')?`<button class="link" data-action="duesForm" data-id="${m.id}">Cập nhật</button>`:''}</td></tr>`).join('')}</tbody></table>`}
views.finance=()=>head('Quỹ & thu chi','Theo dõi đóng quỹ, dự trù và các giao dịch được ghi nhận.',can('finance')?`<div>${button('＋ Ghi khoản thu','income','',true)} ${button('− Ghi khoản chi','expense')}</div>`:'')+sourceLine()+`<div class="stats">${metric('↗','Quỹ thực thu theo nguồn',money(seed.finance.received),'10 người đã nộp theo bảng tổng hợp')}${metric('◈','Tổng quỹ dự kiến',money(seed.finance.expected),`${seed.finance.basisMembers} người × ${money(seed.finance.monthlyFee)}`)}${metric('↘','Tổng chi phí dự kiến',money(sum(db.budget)),'Kế hoạch chi, chưa phải thực chi')}${metric('◫','Dư quỹ dự kiến theo nguồn',money(seed.finance.projectedBalance),'Dự kiến thu − dự kiến chi')}</div>${discrepancy()}<section class="panel"><div class="panelhead"><h2>${can('finance')?'Theo dõi đóng quỹ tháng đầu':'Đóng quỹ của bạn'}</h2>${button('↓ Xuất trạng thái','exportDues')}</div><p class="muted">Mức đóng theo nguồn: ${money(seed.finance.monthlyFee)}/người. Nguồn chưa có ngày thu và số tiền từng người; trạng thái dưới đây không được cộng thêm vào số thực thu.</p>${can('finance')?'<div class="filters"><input id="duesSearch" placeholder="Tìm tên, lớp…"><select id="duesStatus"><option value="">Tất cả trạng thái</option><option>Đã đóng</option><option>Chưa đóng</option></select></div>':''}<div class="tablewrap" id="duesTable">${duesRows(can('finance')?db.members:db.members.filter(m=>m.id===userId))}</div></section><section class="panel"><div class="panelhead"><h2>Dự trù chi phí</h2>${can('finance')?button('＋ Thêm dự trù','budgetForm'):''}</div><div class="tablewrap"><table><thead><tr><th>HẠNG MỤC</th><th>SỐ LƯỢNG</th><th>ĐƠN GIÁ</th><th>THÀNH TIỀN</th><th>PHỤ TRÁCH / TẦN SUẤT</th><th></th></tr></thead><tbody>${db.budget.map(b=>`<tr><td class="table-note"><b>${esc(b.title)}</b><p class="muted">${esc(b.note)}</p></td><td>${b.quantity} ${esc(b.unit)}</td><td>${money(b.unitPrice)}</td><td><b>${money(b.amount)}</b></td><td>${esc(b.owner)}<p class="muted">${esc(b.frequency)}</p></td><td>${can('finance')?`<button class="link" data-action="budgetForm" data-id="${b.id}">Sửa</button>`:''}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><div class="panelhead"><h2>Giao dịch bổ sung trên website</h2>${button('↓ Xuất CSV','exportFinance')}</div><div class="notice">Bảng nguồn chưa có sổ giao dịch và tổng thực chi. Số dư tiền thực tế chưa xác định. Các khoản dưới đây là dữ liệu bổ sung trên website, chưa đồng bộ với Sheets.</div><div class="filters"><input id="txSearch" placeholder="Tìm nội dung…"><select id="txType"><option value="">Thu & chi</option><option>Thu</option><option>Chi</option></select><select id="txCategory"><option value="">Mọi danh mục</option>${categories.map(c=>`<option>${c}</option>`).join('')}</select><input id="txFrom" type="date" aria-label="Từ ngày"><input id="txTo" type="date" aria-label="Đến ngày"></div><div id="txTable" class="tablewrap">${txTable(financeTx())}</div><p id="txSummary" class="muted">Thu bổ sung: ${money(sum(financeTx().filter(t=>t.type==='Thu')))} · Chi bổ sung: ${money(sum(financeTx().filter(t=>t.type==='Chi')))}</p></section>`;
function canTask(t){return isAdmin()||can('events')&&/Chuyên môn|Quản lý đội/i.test(t.department)||can('logistics')&&/Hậu cần/i.test(t.department)||can('media')&&/Truyền thông/i.test(t.department)||can('finance')&&/Tài chính/i.test(t.department)}
function taskRows(limit,rows=db.tasks){return (limit?rows.slice(0,limit):rows).map(t=>`<div class="row"><span class="status-dot ${t.status==='Hoàn thành'?'done':''}"></span><div class="grow"><b class="${t.status==='Hoàn thành'?'taskdone':''}">${esc(t.title)}</b><p>${esc(t.department)} · ${esc(t.owner||'Chưa phân công')}</p><p>Hạn: ${t.deadline?date(t.deadline):esc(t.deadlineText||'Chưa có hạn')}</p></div>${tag(t.status)}${canTask(t)?`<button class="link" data-action="taskForm" data-id="${t.id}">Sửa</button>`:''}</div>`).join('')||'<div class="empty">Không có công việc phù hợp.</div>'}
views.logistics=()=>head('Công việc câu lạc bộ','Theo dõi đầu việc theo từng ban và người phụ trách.',button('＋ Thêm công việc','taskForm','',true))+sourceLine()+`<section class="panel"><div class="filters"><input id="taskSearch" placeholder="Tìm công việc, người phụ trách…"><select id="taskDept"><option value="">Tất cả các ban</option>${departments().map(d=>`<option>${esc(d)}</option>`).join('')}</select><select id="taskStatus"><option value="">Tất cả trạng thái</option>${['Chưa làm','Đang làm','Hoàn thành'].map(s=>`<option>${s}</option>`).join('')}</select></div><div id="taskList">${taskRows()}</div></section>`;
views.media=()=>head('Ban Truyền thông','Đầu việc truyền thông từ nguồn và nội dung CLB.',button('＋ Tạo bài viết','postForm','',true))+sourceLine()+`<section class="panel"><div class="panelhead"><h2>Đầu việc truyền thông</h2>${button('＋ Thêm công việc','mediaTask')}</div>${taskRows(null,db.tasks.filter(t=>/Truyền thông/i.test(t.department)))}</section><section class="panel"><div class="panelhead"><h2>Bài viết & lịch đăng</h2></div><div class="filters"><input id="postSearch" placeholder="Tìm bài viết…"><select id="postStatus"><option value="">Tất cả trạng thái</option>${['Bản nháp','Chờ duyệt','Đã đăng'].map(s=>`<option>${s}</option>`).join('')}</select></div><div id="postList">${postRows(db.posts)}</div><p class="muted">Tab truyền thông trong nguồn chưa có bài viết. Bạn có thể tạo nội dung mới tại đây.</p></section>`;
views.venues=()=>head('Sân bóng & lịch dự kiến',`${db.venues.length} sân trong danh sách khảo sát.`,can('events')||can('logistics')?button('＋ Thêm sân','venueForm','',true):'')+sourceLine()+`<div class="notice">Lịch dự kiến: Thứ 5, 19h30 – 21h00. Chọn sân và chốt khảo sát không tự tạo lịch đá cụ thể.</div><div class="venue-grid">${db.venues.map(v=>`<section class="panel venue-card"><div class="panelhead"><span class="avatar">⌖</span>${tag(v.confirmed?'Đã chốt':v.survey)}</div><h2>${esc(v.name)}</h2><p>${esc(v.weekday)} · ${esc(v.time)}</p><p class="muted">Địa điểm: ${esc(v.place||'Chưa cập nhật')}</p><p>Giá thương lượng: <b>${amount(v.price)}</b></p>${button('Cập nhật khảo sát','venueForm',v.id)}</section>`).join('')}</div>`;
views.rules=()=>head('Nội quy câu lạc bộ','Giữ tinh thần kỷ luật, tôn trọng và fair-play.')+sourceLine()+`<section class="panel"><h2>${esc(db.rules.title)}</h2><div class="rules-content">${esc(db.rules.text)}</div></section>`;
views.source=()=>head('Dữ liệu nguồn','Thông tin đối chiếu giữa website và Google Sheets.',`<a class="btn" href="${esc(seed.source.url)}" target="_blank" rel="noopener">Mở bảng tính ↗</a>`)+`<section class="panel"><div class="panelhead"><h2>Bản dữ liệu nhập ngày ${date(seed.source.snapshotDate)}</h2>${isAdmin()?button('↓ Sao lưu dữ liệu website','exportBackup'):''}</div><div class="import-summary"><p><b>${seed.summary.memberCount}</b> thành viên · <b>${seed.summary.taskCount}</b> đầu việc · <b>${seed.summary.venueCount}</b> sân khảo sát · <b>${seed.summary.budgetCount}</b> khoản dự trù.</p></div>${discrepancy()}<p>Website giữ nguyên họ tên, lớp, vị trí, tình trạng tham gia và đóng quỹ. Nội quy được nhập nguyên văn. Các ngày hạn từ bảng tính được chuyển sang định dạng ngày Việt Nam.</p><p>Bản cũ có dữ liệu mẫu được giữ trong bộ nhớ riêng. Thay đổi mới không ghi đè Google Sheets và không tự cập nhật khi Sheets thay đổi.</p><p class="muted">Ảnh bill chỉ gắn với thành viên khi vị trí ảnh trong tệp xác định được dòng. Các ảnh chưa xác định người nhận được giữ riêng để đối chiếu.</p><div class="actions">${isAdmin()?button('Xem ảnh chưa gắn thành viên','unassignedReceipts'):''}</div></section><section class="panel"><h2>Các tab đã đọc</h2>${seed.source.sheets.map(s=>`<div class="row"><div class="grow"><b>${esc(s.name)}</b></div><span class="muted">${s.nonemptyRows} dòng có dữ liệu</span></div>`).join('')}</section>`;
views.profile=()=>{const m=me();if(m.accessOnly)return head('Không gian quản lý',esc(m.role))+`<section class="panel"><h2>${esc(m.name)}</h2><p>Đây là vai trò dùng thử, không phải thành viên trong danh sách CLB. Đăng xuất và chọn một thành viên để cập nhật hồ sơ hoặc gửi đơn xin vắng.</p>${button('Đổi tài khoản','logout')}</section>`;return head('Hồ sơ cá nhân',`${esc(m.name)} · ${esc(m.unit)}`,button('Chỉnh sửa hồ sơ','profileForm','',true))+`<section class="panel"><div class="row"><span class="avatar">${initials(m.name)}</span><div class="grow"><h2>${esc(m.name)}</h2><p>${esc(m.sourcePosition)}</p></div>${tag(m.status)}</div><div class="formgrid">${[['Lớp / Bộ phận',m.unit],['Email',m.email||'Chưa cập nhật'],['Điện thoại',m.phone||'Chưa cập nhật'],['Đóng quỹ tháng đầu',m.duesStatus],['Ngày tham gia',date(m.joined)],['Vai trò truy cập',m.role]].map(([k,v])=>`<div><p class="muted">${k}</p><b>${esc(v)}</b></div>`).join('')}</div></section><section class="panel"><h2>Lịch sử tham gia</h2>${eventRows(db.events.filter(e=>e.rsvps[userId]||e.attendance[userId]))}</section>`};
function taskForm(id,dept){const t=db.tasks.find(t=>t.id===id)||{id:uid(),title:'',department:dept||departments().find(d=>canTask({department:d}))||'',owner:'',deadline:'',deadlineText:'',status:'Chưa làm',note:'',event:''};if(!canTask(t))return toast('Vai trò hiện tại không quản lý ban này.');const editableDepts=departments().filter(d=>canTask({department:d}));modal(id?'Cập nhật đầu việc':'Thêm đầu việc',form(`${field('Công việc','title',t.title)}${select('Ban phụ trách','department',editableDepts,t.department)}${field('Người đảm nhiệm','owner',t.owner,'text',false)}<div class="formgrid">${field('Hạn theo ngày','deadline',t.deadline,'date',false)}${field('Hạn theo mô tả','deadlineText',/^\d+(?:\.\d+)?$/.test(t.deadlineText)?'':t.deadlineText,'text',false)}</div>${select('Tiến độ','status',['Chưa làm','Đang làm','Hoàn thành'],t.status)}${area('Ghi chú','note',t.note)}`));handleForm(d=>{if(!canTask({department:d.department}))throw Error('Không có quyền quản lý ban này.');Object.assign(t,d,{localUpdatedAt:new Date().toISOString()});if(!id)db.tasks.push(t)})}
function bindSource(root=document){bindBase(root);const on=(id,fn)=>{const el=$('#'+id);if(el)el.oninput=fn};['memberSearch','memberPosition','memberStatus','memberDues'].forEach(id=>on(id,()=>{$('#memberTable').innerHTML=memberTable(filteredMembers());bind($('#memberTable'))}));['taskSearch','taskDept','taskStatus'].forEach(id=>on(id,()=>{const value=i=>$('#'+i)?.value||'';$('#taskList').innerHTML=taskRows(null,db.tasks.filter(t=>(t.title+t.owner).toLowerCase().includes(value('taskSearch').toLowerCase())&&(!value('taskDept')||t.department===value('taskDept'))&&(!value('taskStatus')||t.status===value('taskStatus'))));bind($('#taskList'))}));['duesSearch','duesStatus'].forEach(id=>on(id,()=>{const q=$('#duesSearch').value.toLowerCase(),status=$('#duesStatus').value;$('#duesTable').innerHTML=duesRows(db.members.filter(m=>(m.name+m.unit).toLowerCase().includes(q)&&(!status||m.duesStatus===status)));bind($('#duesTable'))}));}
function showReceipts(receipts,title){modal(title,receipts.length?receipts.map(r=>`<figure style="margin:0 0 20px"><img src="${esc(r.path)}" alt="Ảnh bill từ bảng nguồn" style="max-width:100%;max-height:650px"><figcaption class="muted">${esc(r.source?.sheet||'Google Sheets')} · ${r.member?'Gắn theo dòng thành viên':'Chưa xác định thành viên'}</figcaption></figure>`).join(''):'<div class="empty">Chưa có ảnh chứng từ.</div>')}
function actionSource(a,id){if(a==='gotoMembers')return go('members');if(a==='gotoFinance')return go('finance');if(a==='gotoRequests')return go('requests');if(a==='taskForm')return taskForm(id);if(a==='mediaTask')return taskForm(null,departments().find(d=>/Truyền thông/i.test(d)));if(a==='exportMembers'){if(can('members'))csv('rikkei-thanh-vien.csv',[['STT','Họ tên','Lớp','Vị trí / vai trò','Tham gia','Đóng quỹ','Ghi chú','Ghi chú 2'],...filteredMembers().map(m=>[m.sourceIndex,m.name,m.unit,m.sourcePosition,m.status,m.duesStatus,m.note,m.note2])]);return}
if(a==='exportDues'){const ms=can('finance')?db.members:db.members.filter(m=>m.id===userId);csv('rikkei-dong-quy.csv',[['Họ tên','Lớp','Kỳ','Mức dự kiến','Trạng thái'],...ms.map(m=>[m.name,m.unit,'Tháng đầu',db.finance.monthlyFee,m.duesStatus])]);return}
if(a==='memberReceipts'){const m=db.members.find(m=>m.id===id);if(!m||!can('finance')&&!can('members')&&m.id!==userId)return;return showReceipts(m.receipts||[],esc(m.name)+' · Ảnh bill')}
if(a==='unassignedReceipts'){if(!isAdmin())return;return showReceipts(db.receipts.filter(r=>!r.member),'Ảnh bill chưa xác định thành viên')}
if(a==='duesForm'){if(!can('finance'))return;const m=db.members.find(m=>m.id===id);modal('Cập nhật đóng quỹ · '+esc(m.name),form(`${select('Trạng thái tháng đầu','duesStatus',['Chưa đóng','Đã đóng'],m.duesStatus)}${area('Ghi chú xác nhận','note2',m.note2)}<p class="muted">Cập nhật trạng thái không tự tạo giao dịch, không sửa số thực thu của bản nguồn. Để ghi số tiền nhận mới, dùng Ghi khoản thu.</p>`));handleForm(d=>{Object.assign(m,d,{localUpdatedAt:new Date().toISOString()});const due=db.dues.find(x=>x.member===id);if(due)due.status=d.duesStatus;notify('Cập nhật trạng thái đóng quỹ',`Tháng đầu: ${d.duesStatus}`,m.id)});return}
if(a==='venueForm'){if(!can('events')&&!can('logistics'))return;const v=db.venues.find(v=>v.id===id)||{id:uid(),name:'',weekday:'Thứ 5',time:'19h30 - 21h',place:'',price:null,survey:'Chưa Khảo Sát',confirmed:false};modal(id?'Cập nhật sân bóng':'Thêm sân bóng',form(`${field('Tên sân','name',v.name)}${field('Địa chỉ','place',v.place,'text',false)}<div class="formgrid">${field('Ngày trong tuần','weekday',v.weekday)}${field('Khung giờ','time',v.time)}</div>${field('Giá thương lượng (đồng)','price',v.price??'','number',false)}${select('Khảo sát','survey',['Chưa Khảo Sát','Đang khảo sát','Đã khảo sát'],v.survey)}${select('Chốt sân','confirmed',[['false','Chưa chốt'],['true','Đã chốt']],String(v.confirmed))}`));handleForm(d=>{if(d.price&&(!Number.isFinite(+d.price)||+d.price<0))throw Error('Giá sân không hợp lệ.');Object.assign(v,d,{price:d.price?+d.price:null,confirmed:d.confirmed==='true'});if(!id)db.venues.push(v)});return}
if(a==='budgetForm'){if(!can('finance'))return;const b=db.budget.find(b=>b.id===id)||{id:uid(),title:'',quantity:1,unit:'',unitPrice:'',frequency:'Một lần',owner:'',note:''};modal(id?'Sửa khoản dự trù':'Thêm khoản dự trù',form(`${field('Hạng mục','title',b.title)}<div class="formgrid">${field('Số lượng','quantity',b.quantity,'number')}${field('Đơn vị','unit',b.unit)}${field('Đơn giá dự kiến','unitPrice',b.unitPrice,'number')}${select('Tần suất','frequency',['Một lần','Định kỳ','Dự phòng','Phát sinh'],b.frequency)}</div>${field('Người phụ trách','owner',b.owner,'text',false)}${area('Ghi chú','note',b.note)}`));handleForm(d=>{if(!Number.isFinite(+d.quantity)||+d.quantity<=0||!Number.isFinite(+d.unitPrice)||+d.unitPrice<=0)throw Error('Số lượng và đơn giá phải lớn hơn 0.');Object.assign(b,d,{quantity:+d.quantity,unitPrice:+d.unitPrice,amount:+d.quantity*+d.unitPrice});if(!id)db.budget.push(b)});return}
if(a==='exportBackup'){if(!isAdmin())return;const url=URL.createObjectURL(new Blob([JSON.stringify(db,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='rikkei-club-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return}
if(a==='deleteMember'&&!isAdmin())return;return actionBase(a,id)}
// All operational departments can view the shared task board; edits remain scoped to their own department.
const originalAllowed = allowed;
allowed = p => p==='logistics' ? !!me()&&[roles[0],roles[1],roles[2],roles[3],roles[4]].includes(currentRole()) : originalAllowed(p);
navItems.find(x=>x[0]==='logistics')[2]='Công việc các ban';
